export const scssOptions = {
  additionalData: '@use "@/assets/styles/mixins" as mix;\n'
};

.order-panel {
  :deep(.library-cell) { padding: 12px 16px; }
}

.document-card {
  &__title { font-weight: 700; }
  &--compact { padding: 12px; }
  &.is-selected { border-color: var(--primary); }
}

.editor-content {
  word-break: keep-all; overflow-wrap: anywhere;
  :deep(ul) { list-style: disc; padding-left: 22px; }
  :deep(a) { text-decoration: underline; }
}

.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid__item { min-width: 0; overflow-wrap: anywhere; }
.table-scroll { overflow-x: auto; }

import cover from '@/assets/tips/project-design.svg';
const cards = [{ id: 'design', image: cover }];
const publicLogo = `${import.meta.env.BASE_URL}tips/guide-mark.svg`;

.list-move, .list-enter-active, .list-leave-active { transition: transform .2s, opacity .2s; }
.list-enter-from, .list-leave-to { opacity: 0; transform: translateY(8px); }
@media (prefers-reduced-motion: reduce) { .list-move, .list-enter-active, .list-leave-active { transition: none; } }

onMounted(() => {
  media = window.matchMedia('(max-width: 760px)');
  mobile.value = media.matches;
  media.addEventListener('change', update);
});
onUnmounted(() => media?.removeEventListener('change', update));

watch(keyword, async (value, _old, onCleanup) => {
  const controller = new AbortController();
  onCleanup(() => controller.abort());
  try {
    const response = await fetch('/api/search?q=' + encodeURIComponent(value), { signal: controller.signal });
    if (!response.ok) throw new Error('검색 실패');
    results.value = await response.json();
  } catch (error) { if (error.name !== 'AbortError') message.value = '검색에 실패했습니다.'; }
});

onMounted(() => window.addEventListener('resize', update));
onUnmounted(() => {
  window.removeEventListener('resize', update);
  observer?.disconnect();
});
